INSERT INTO actual_order_products (actual_order_id, product_id) SELECT (SELECT MAX(actual_order_id) FROM (SELECT * FROM actual_orders_recent UNION ALL SELECT * FROM actual_orders_completed) AS actual_orders) AS actual_order_id, rop.product_id FROM regular_order_products AS rop WHERE rop.regular_order_id = (SELECT MAX(regular_order_id) FROM regular_orders) ORDER BY rop.product_id ASC LIMIT 1